-- ==============================================================================
-- NANDHA ENGINEERING COLLEGE (NEC-SCS) — COMPREHENSIVE SAMPLE DATABASE FEED
-- Populates all Departments (UG & PG), Faculty, Students, Certificates, Points,
-- Reviews, Categories, and Audit Logs.
-- ==============================================================================

-- 1. College
VALUES ('11111111-1111-1111-1111-111111111111', 'Nandha Engineering College (NEC)', 'NEC', '/logo.svg')
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name;

-- 2. Settings
VALUES ('22222222-2222-2222-2222-222222222222', '11111111-1111-1111-1111-111111111111', 100, 30, 10)
ON CONFLICT (id) DO NOTHING;

-- 3. Departments
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, code = EXCLUDED.code, type = EXCLUDED.type;

-- 4. Categories
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description;

-- 5. Profiles (Admin, Faculty, Students)
ON CONFLICT (id) DO UPDATE SET email = EXCLUDED.email, full_name = EXCLUDED.full_name;

-- 6. Faculty
ON CONFLICT (id) DO UPDATE SET designation = EXCLUDED.designation, is_hod = EXCLUDED.is_hod;

-- 7. Students
ON CONFLICT (id) DO UPDATE SET register_number = EXCLUDED.register_number, academic_year = EXCLUDED.academic_year;

-- 8. Certificates
ON CONFLICT (id) DO UPDATE SET status = EXCLUDED.status, achievement_id = EXCLUDED.achievement_id;

-- 9. Certificate Files
ON CONFLICT (id) DO NOTHING;

-- 10. Certificate Reviews
ON CONFLICT (id) DO NOTHING;

-- 11. Point Records
ON CONFLICT (id) DO NOTHING;
